WITH unpacked AS (SELECT id, service, latency_ms, status_code, payload_json, context['region'] AS region, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, ARRAY_CONTAINS(MAP_KEYS(context), 'trace') AS has_trace, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 2) != 0 AS INT) AS is_flagged FROM app_logs WHERE status_code > 424) SELECT CASE WHEN latency_ms >= 1974 THEN 'PREMIUM' ELSE 'STANDARD' END AS latency_ms_tier, SIZE(COLLECT_SET(service)) AS num_services, COUNT(CASE WHEN service = 'billing' THEN 1 END) AS billing_count, SUM(status_code_high) FILTER (WHERE service = 'checkout') AS checkout_total_status_code_high FROM unpacked GROUP BY 1 HAVING COUNT(CASE WHEN service = 'billing' THEN 1 END) > 1 ORDER BY billing_count ASC
